		return existing;
	}

	const turn = document.createElement("div");
	turn.className = "turn " + (entry.role === "caller" ? "caller" : "agent");
	turn.classList.toggle("pending", Boolean(entry.pending));
	if (entry.id) turn.dataset.clipId = entry.id;

